// Chọn form đăng ký và ô nhập họ tên
const registerForm = document.querySelector('#registerForm');
const fullNameInput = document.querySelector('#fullName');

// Đăng ký sự kiện submit cho form
registerForm.addEventListener('submit', function(event) {
  // Ngăn hành vi gửi form mặc định của trình duyệt (chống reload trang)
  event.preventDefault();

  // Lấy giá trị người dùng vừa nhập vào ô input
  const fullNameValue = fullNameInput.value;

  console.log('Họ và tên khách hàng:', fullNameValue);
});

// Chọn các phần tử DOM cần thiết
const registerForm = document.querySelector('#registerForm');
const fullNameInput = document.querySelector('#fullName');
const emailInput = document.querySelector('#email');
const termsCheckbox = document.querySelector('#agreeTerms');
const resultMessage = document.querySelector('#resultMessage');

// Xử lý sự kiện submit form
registerForm.addEventListener('submit', function(event) {
  event.preventDefault();

  // Lấy dữ liệu từ các input khác nhau
  const fullName = fullNameInput.value;
  const email = emailInput.value;
  const hasAgreedTerms = termsCheckbox.checked;

  // Hiển thị kết quả đăng ký lên giao diện
  resultMessage.textContent = `Khách hàng: ${fullName} | Email: ${email} | Đồng ý điều khoản: ${hasAgreedTerms ? 'Có' : 'Không'}`;
});

// Chọn form và các phần tử input
const registerForm = document.querySelector('#registerForm');
const fullNameInput = document.querySelector('#fullName');
const emailInput = document.querySelector('#email');
const passwordInput = document.querySelector('#password');
const termsCheckbox = document.querySelector('#agreeTerms');
const statusNotification = document.querySelector('#statusNotification');

// Xử lý sự kiện submit với validation hoàn chỉnh
registerForm.addEventListener('submit', function(event) {
  // Ngăn hành vi tải lại trang
  event.preventDefault();

  // Lấy và cắt khoảng trắng thừa ở đầu/cuối của chuỗi nhập
  const fullName = fullNameInput.value.trim();
  const email = emailInput.value.trim();
  const password = passwordInput.value;
  const isAgreed = termsCheckbox.checked;

  // 1. Kiểm tra Họ tên không được rỗng
  if (fullName === '') {
    statusNotification.textContent = 'Vui lòng nhập Họ và tên!';
    return;
  }

  // 2. Kiểm tra Email không được rỗng
  if (email === '') {
    statusNotification.textContent = 'Vui lòng nhập địa chỉ Email!';
    return;
  }

  // 3. Kiểm tra độ dài mật khẩu
  if (password.length < 6) {
    statusNotification.textContent = 'Mật khẩu phải chứa ít nhất 6 ký tự!';
    return;
  }

  // 4. Kiểm tra việc đồng ý điều khoản dịch vụ
  if (!isAgreed) {
    statusNotification.textContent = 'Bạn phải đồng ý với Điều khoản dịch vụ để tiếp tục!';
    return;
  }

  // Nếu tất cả kiểm tra đều vượt qua
  statusNotification.textContent = 'Đăng ký tài khoản thành công! Xin chào ' + fullName;
});

